-- Q1094: Pension and Postretirement Benefits [hard/L2]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["The corridor is $600,000 (10% of the greater of PBO or plan assets); excess of $150,000 is amortized at $15,000 per year over 10 years","The full $750,000 is amortized over 10 years at $75,000 per year because all actuarial losses must be systematically amortized","No amortization is required because $750,000 is less than both the PBO and the plan assets balances","The corridor equals $750,000 so the excess is $0 and no corridor amortization occurs in this period"]$EXPL$::jsonb,
