  choices = $EXPL$["Both statements treat both payments as expenses in the period paid with no reconciling difference between them","Fund statements report both as expenditures; government-wide statements treat principal as a liability reduction and only interest as expense","The principal payment is capitalized on both statements because it represents an investment in reducing future obligations","Interest is the only reconciling item because principal payments are treated identically on both financial statements"]$EXPL$::jsonb,
